/* === File: chain-calc.js === */

/**
 * MITCalc Web App - Roller Chain Engineering Calculation Engine (Module 9)
 * Standards: ISO 606 / DIN 8187 / DIN 8188 / ASME B29.1M
 * Rule 1: Zero-Force Scope Protocol (No forces/stresses, pure kinematics & geometry).
 * Rule 6: Zero-Tolerance Precision Delta = 0.000000.
 */

const ChainCalc = {
    /**
     * Core transmission calculation
     * @param {Object} params
     *   - units: 1 (Metric mm/kW/Nm) or 2 (Imperial in/HP/lb-in)
     *   - stdId: 'EU_STD', 'US_STD', 'US_ASME', 'US_HEAVY'
     *   - chainId: chain ID or code
     *   - P: Power [kW or HP]
     *   - n1: Driver speed [rpm]
     *   - n2_req: Desired driven speed [rpm]
     *   - z1: Number of teeth on sprocket 1
     *   - z2: Number of teeth on sprocket 2
     *   - a_req: Desired axis distance [mm or in]
     *   - linksMode: 'even', 'odd', or 'auto'
     *   - linksCustom: custom number of links (optional)
     *   - drivingType: 'A', 'B', 'C'
     *   - drivenType: 'A', 'B', 'C', 'D'
     */
    calculate(params) {
        const units = params.units || 1; // 1: Metric, 2: Imperial
        const isMetric = units === 1;

        // 1. Get chain record from ChainData
        let chain = null;
        if (typeof ChainData !== 'undefined') {
            const std = ChainData.standards.find(s => s.id === (params.stdId || 'EU_STD')) || ChainData.standards[0];
            if (std && std.chains) {
                if (typeof params.chainId === 'number') {
                    chain = std.chains.find(c => c.id === params.chainId) || std.chains[0];
                } else if (typeof params.chainId === 'string') {
                    chain = std.chains.find(c => c.code === params.chainId || c.name === params.chainId) || std.chains[0];
                } else {
                    chain = std.chains[0];
                }
            }
        }

        // Fallback default: ISO 08B-1 (p=12.7mm)
        if (!chain) {
            chain = {
                id: 4,
                name: '08B - 1  (0.5)',
                code: '08B-1',
                pitch: 12.7,
                strands: 1,
                fb: 18000,
                mass: 0.70,
                area: 50.0,
                b1: 7.75,
                b2: 11.30,
                d1: 4.45,
                d3: 8.51,
                l: 17.0,
                lc: 18.2,
                g: 11.8,
                s1: 1.6,
                s2: 1.6,
                e: 0.0
            };
        }

        // Unit conversion factors
        const p_mm = chain.pitch; // mm
        const p = isMetric ? p_mm : p_mm / 25.4; // pitch in active units

        // Section 1.0 Input Power & Kinematics
        const P = Math.max(0.001, parseFloat(params.P) || 5.5);
        const n1 = Math.max(1.0, parseFloat(params.n1) || 1450.0);
        let n2_req = parseFloat(params.n2_req);
        if (isNaN(n2_req) || n2_req <= 0) n2_req = n1 / 2.0;

        const i_req = n1 / n2_req;

        // Teeth numbers
        const z1 = Math.max(7, parseInt(params.z1) || 19);
        let z2 = parseInt(params.z2);
        if (isNaN(z2) || z2 < 7) {
            z2 = Math.round(z1 * i_req);
        }

        const i_act = z2 / z1;
        const n2_act = n1 / i_act;
        const i_diff_pct = Math.abs(i_act - i_req) / i_req * 100.0;

        // Torques
        const eta = 0.98; // Chain transmission efficiency
        const Mk1 = isMetric ? (P * 9550.0 / n1) : (P * 5252.0 / n1 * 12.0); // Nm or lb-in
        const Mk2 = isMetric ? (P * 9550.0 / n2_act * eta) : (P * 5252.0 / n2_act * eta * 12.0);

        // Section 3.0 Geometry & Pitch Diameters
        const d1 = p / Math.sin(Math.PI / z1);
        const d2 = p / Math.sin(Math.PI / z2);

        // Desired axis distance
        let a_req = parseFloat(params.a_req);
        if (isNaN(a_req) || a_req <= 0) {
            a_req = 40.0 * p; // Recommended optimum 40 * pitch
        }

        // Theoretical number of links
        const kx_geom = ((z2 - z1) / (2.0 * Math.PI)) ** 2;
        const X_exact = (2.0 * a_req / p) + ((z1 + z2) / 2.0) + (kx_geom * p / a_req);

        // Selected link count
        let X;
        if (params.linksCustom && parseInt(params.linksCustom) > 0) {
            X = parseInt(params.linksCustom);
        } else if (params.linksMode === 'odd') {
            X = Math.round(X_exact);
            if (X % 2 === 0) X += 1;
        } else {
            // Default: Even link count (standard)
            X = Math.floor(X_exact / 2.0 + 0.5) * 2;
        }

        // Min constructional axis distance
        const a_min = (d1 + d2) / 2.0 + (p * 0.5);
        const a_max = 80.0 * p;

        // Actual axis distance a based on integer link count X
        const Kx = X - (z1 + z2) / 2.0;
        const discr = Kx * Kx - (2.0 * (z2 - z1) * (z2 - z1)) / (Math.PI * Math.PI);
        let a = a_req;
        if (discr >= 0) {
            a = (p / 4.0) * (Kx + Math.sqrt(discr));
        }

        // Chain length
        const L = X * p;

        // Peripheral chain speed
        const v = isMetric ? (z1 * p * n1 / 60000.0) : (z1 * p * n1 / (12.0 * 60.0)); // m/s or ft/s
        const v_metric = (z1 * p_mm * n1) / 60000.0; // always m/s for checks

        // Max speed recommendations
        const v_max_metric = 25.0; // m/s with force lubrication

        // Section 4.0 Operating & Quality Indexes
        // Angle of wrap on sprocket 1
        const sin_phi = Math.min(1.0, Math.max(-1.0, (d2 - d1) / (2.0 * a)));
        const phi_rad = Math.asin(sin_phi);
        const phi_deg = phi_rad * 180.0 / Math.PI;
        const alpha1 = 180.0 - 2.0 * phi_deg;
        const alpha2 = 180.0 + 2.0 * phi_deg;

        // Speed variation (Polygonal effect)
        const speed_var_pct = (1.0 / Math.cos(Math.PI / z1) - 1.0) * 100.0;

        // Max slackness / sag y
        const y_slack = 0.02 * a; // 2% of axis distance

        // Joint impact frequency
        const f_impact = (z1 * n1) / (60.0 * X); // 1/s

        // Lubrication recommendation
        let rec_lub_id = 1;
        if (v_metric > 12.0) rec_lub_id = 4;
        else if (v_metric > 7.0) rec_lub_id = 3;
        else if (v_metric > 4.0) rec_lub_id = 2;

        // Section 5.0 ISO 606 / DIN 8187 Sprocket Dimensions
        const d3 = isMetric ? chain.d3 : chain.d3 / 25.4;
        const d1_pin = isMetric ? chain.d1 : chain.d1 / 25.4;
        const b1 = isMetric ? chain.b1 : chain.b1 / 25.4;
        const b2 = isMetric ? chain.b2 : chain.b2 / 25.4;
        const strands = chain.strands || 1;
        const e_trans = isMetric ? chain.e : chain.e / 25.4;

        // Tip diameter Da (ISO 606)
        const da1_min = d1 + 0.5 * d3;
        const da1_max = d1 + 1.25 * p - d3;
        const da1 = (da1_min + da1_max) / 2.0;

        const da2_min = d2 + 0.5 * d3;
        const da2_max = d2 + 1.25 * p - d3;
        const da2 = (da2_min + da2_max) / 2.0;

        // Root radius R1 (ISO 606 / MITCalc: power 0.33)
        const d3_mm = chain.d3;
        const r1_min_mm = 0.505 * d3_mm;
        const r1_max_mm = 0.505 * d3_mm + 0.069 * (d3_mm ** 0.33);
        const R1_raw = (r1_min_mm + r1_max_mm) / 2.0;
        const R1_val = isMetric ? R1_raw : R1_raw / 25.4;
        const RA = isMetric ? 2 : 3;
        const R1 = Number(R1_val.toFixed(RA));

        // Root diameter Df (Bottom of tooth gullet): Df = d - 2 * R1
        const df1 = Number((d1 - 2.0 * R1).toFixed(RA));
        const df2 = Number((d2 - 2.0 * R1).toFixed(RA));

        // Flank radius R2
        const r2_1_min_mm = 0.12 * d3_mm * (z1 + 2);
        const r2_1_max_mm = 0.008 * d3_mm * (z1 * z1 + 180);
        const R2_1_mm = (r2_1_min_mm + r2_1_max_mm) / 2.0;
        const R2_1 = isMetric ? R2_1_mm : R2_1_mm / 25.4;

        const r2_2_min_mm = 0.12 * d3_mm * (z2 + 2);
        const r2_2_max_mm = 0.008 * d3_mm * (z2 * z2 + 180);
        const R2_2_mm = (r2_2_min_mm + r2_2_max_mm) / 2.0;
        const R2_2 = isMetric ? R2_2_mm : R2_2_mm / 25.4;

        // Flank angle alpha
        const flank_alpha1 = 130.0 - 90.0 / z1;
        const flank_alpha2 = 130.0 - 90.0 / z2;

        // Tooth width bf
        let bf_factor = 0.95;
        if (p_mm < 12.7) {
            bf_factor = strands === 1 ? 0.93 : (strands === 2 ? 0.91 : 0.88);
        } else {
            bf_factor = strands === 1 ? 0.95 : (strands === 2 ? 0.93 : 0.93);
        }
        const bf = bf_factor * b1;

        // Total width for multi-strand sprockets
        const B_tot = strands === 1 ? bf : (strands - 1) * e_trans + bf;

        // Chamfer width ba & radius rx
        const ba = 0.125 * d3;
        const rx = 1.5 * d1_pin;

        // Tooth depth f & Rim diameter Dg
        const f = 0.7 * p;
        const Dg1 = d1 - 2.0 * f;
        const Dg2 = d2 - 2.0 * f;

        // Weight estimation
        const chain_weight = (L * (chain.mass || 0.70)) / (isMetric ? 1000.0 : 1.0);

        // Nested sprocket objects for direct access
        const sprocket1 = {
            d: d1,
            da: da1,
            df: df1,
            R1: R1,
            R2: R2_1,
            bf1: bf,
            rx: rx,
            Dg: Dg1,
            p: p,
            d3: d3,
            alphaDeg: flank_alpha1
        };

        const sprocket2 = {
            d: d2,
            da: da2,
            df: df2,
            R1: R1,
            R2: R2_2,
            bf1: bf,
            rx: rx,
            Dg: Dg2,
            p: p,
            d3: d3,
            alphaDeg: flank_alpha2
        };

        // Recommended lubrication description string
        let lubrication = 'Bôi trơn nhỏ giọt (Drip lubrication)';
        if (rec_lub_id === 2) lubrication = 'Bôi trơn ngâm dầu (Oil bath)';
        else if (rec_lub_id === 3) lubrication = 'Bôi trơn cưỡng bức áp lực (Force-feed / Pressure spray)';

        return {
            units,
            isMetric,
            chain,
            p,
            p_mm,
            strands,

            // Kinematics (Section 1.0)
            P,
            n1,
            n2_req,
            n2_act,
            n2: n2_act,
            i_req,
            i_act,
            i: i_act,
            i_diff_pct,
            Mk1,
            Mk2,

            // Transmission Geometry (Section 3.0)
            z1,
            z2,
            d1,
            d2,
            a_req,
            a,
            a_min,
            a_max,
            X_exact,
            X,
            X_even: X,
            L,
            v,
            v_metric,
            v_max_metric,

            // Quality & Operating Indexes (Section 4.0)
            alpha1,
            alpha2,
            speed_var_pct,
            y_slack,
            y: y_slack,
            f_impact,
            rec_lub_id,
            lubrication,

            // ISO 606 Sprocket Dimensions (Section 5.0)
            d3,
            d1_pin,
            b1,
            b2,
            da1,
            da2,
            df1,
            df2,
            R1,
            R2_1,
            R2_2,
            flank_alpha1,
            flank_alpha2,
            bf,
            B_tot,
            ba,
            rx,
            f,
            Dg1,
            Dg2,
            chain_weight,

            // Nested sprocket structures
            sprocket1,
            sprocket2
        };
    },

    /**
     * Generate 2D Profile Points for a Sprocket Tooth (ISO 606)
     */
    /**
     * Generate 2D Profile Points for a Sprocket Tooth (ISO 606 / DIN 8196 / ASME B29.1M)
     * Authentic closed analytical contour:
     * - Roller seating arc R1 (subtending angle alpha)
     * Generate 2D Profile Points for a Sprocket Tooth (ISO 606 / DIN 8196 / MITCalc 1.74)
     * Authentic analytical contour:
     * - Roller seating arc R1 (subtending angle alpha = 130 - 90/z deg)
     * - Flank arc R2 tangent C1 to R1
     * - Crest arc along tip circle da/2 (Top Land) connecting flanks across tooth centerline (NO artificial dome/topping bulb)
     * - 100% conjugate alignment with roller meshing positions (Space 0 at 0.0 rad)
     */
    generateSprocket2DPoints(z, pOrData, d3, da, df, R1, R2, alphaDeg) {
        let p, d3_val, da_val, df_val, R1_val, R2_val, alpha_val;
        if (typeof pOrData === 'object' && pOrData !== null) {
            p = pOrData.p || 12.7;
            d3_val = pOrData.d3 || 8.51;
            da_val = pOrData.da || (p / Math.sin(Math.PI / z) + 0.625 * p - 0.25 * d3_val);
            df_val = pOrData.df || (p / Math.sin(Math.PI / z) - 2.0 * (0.505 * d3_val));
            R1_val = pOrData.R1 || (0.505 * d3_val);
            R2_val = pOrData.R2 || (0.12 * d3_val * (z + 2) + 0.008 * d3_val * (z * z + 180)) / 2.0;
            alpha_val = pOrData.alphaDeg || (130.0 - 90.0 / z);
        } else {
            p = pOrData || 12.7;
            d3_val = d3 || 8.51;
            da_val = da || (p / Math.sin(Math.PI / z) + 0.625 * p - 0.25 * d3_val);
            df_val = df || (p / Math.sin(Math.PI / z) - 2.0 * (0.505 * d3_val));
            R1_val = R1 || (0.505 * d3_val);
            R2_val = R2 || (0.12 * d3_val * (z + 2) + 0.008 * d3_val * (z * z + 180)) / 2.0;
            alpha_val = alphaDeg || (130.0 - 90.0 / z);
        }

        const dp = p / Math.sin(Math.PI / z);
        const rp = dp / 2.0;
        const ra = da_val / 2.0;
        const alpha = (alpha_val * Math.PI) / 180.0;
        const pitch_ang = (2.0 * Math.PI) / z;
        const half_pitch = Math.PI / z;

        // MITCalc analytical law of cosines geometry:
        // mc_P3 is the contact point between R1 and R2
        const mc_P3_x = R1_val * Math.sin(alpha / 2.0);
        const mc_P3_y = rp - R1_val * Math.cos(alpha / 2.0);
        const mc_P7_x = mc_P3_x + R2_val * Math.sin(alpha / 2.0);
        const mc_P7_y = mc_P3_y - R2_val * Math.cos(alpha / 2.0);

        const b = Math.hypot(mc_P7_x, mc_P7_y);
        const c = ra;
        const a_side = R2_val;
        const cos_alf = (b * b + c * c - a_side * a_side) / (2.0 * b * c);
        const alf_triangle = Math.acos(Math.min(1.0, Math.max(-1.0, cos_alf)));

        const ang_P7_native = Math.atan2(mc_P7_x, mc_P7_y);
        const th5 = ang_P7_native - alf_triangle; // Angle from space center to flank-crest junction

        // In space frame along positive X (Space 0 center at (rp, 0)):
        const p3_bot = { x: rp - R1_val * Math.cos(alpha / 2.0), y: -R1_val * Math.sin(alpha / 2.0) };
        const p3_top = { x: rp - R1_val * Math.cos(alpha / 2.0), y: +R1_val * Math.sin(alpha / 2.0) };

        const P7_bot = { x: p3_bot.x - R2_val * Math.cos(alpha / 2.0), y: p3_bot.y - R2_val * Math.sin(alpha / 2.0) };
        const P7_top = { x: p3_top.x - R2_val * Math.cos(alpha / 2.0), y: p3_top.y + R2_val * Math.sin(alpha / 2.0) };

        const p5_bot = { x: ra * Math.cos(-th5), y: ra * Math.sin(-th5) };
        const p5_top = { x: ra * Math.cos(th5), y: ra * Math.sin(th5) };

        const phi_bot_start = Math.atan2(p5_bot.y - P7_bot.y, p5_bot.x - P7_bot.x);
        const phi_bot_end = Math.atan2(p3_bot.y - P7_bot.y, p3_bot.x - P7_bot.x);

        const phi_top_start = Math.atan2(p3_top.y - P7_top.y, p3_top.x - P7_top.x);
        const phi_top_end = Math.atan2(p5_top.y - P7_top.y, p5_top.x - P7_top.x);

        // Discretization resolutions:
        const n_tip = 3;
        const n_flank = 8;
        const n_seat = 6;

        // Sample 1 pitch sector [-half_pitch, +half_pitch]:
        const sector = [];

        // 1. Bottom crest arc: [-half_pitch, -th5] on circle ra
        for (let j = 0; j < n_tip; j++) {
            const u = j / n_tip;
            const th = -half_pitch + u * (half_pitch - th5);
            sector.push({ x: ra * Math.cos(th), y: ra * Math.sin(th) });
        }

        // 2. Bottom flank arc: [p5_bot -> p3_bot] on circle R2
        for (let j = 0; j < n_flank; j++) {
            const u = j / n_flank;
            const phi = phi_bot_start + u * (phi_bot_end - phi_bot_start);
            sector.push({ x: P7_bot.x + R2_val * Math.cos(phi), y: P7_bot.y + R2_val * Math.sin(phi) });
        }

        // 3. Seating arc: [p3_bot -> p3_top] on circle R1
        for (let j = 0; j < n_seat; j++) {
            const u = j / n_seat;
            const beta = -alpha / 2.0 + u * alpha;
            sector.push({ x: rp - R1_val * Math.cos(beta), y: R1_val * Math.sin(beta) });
        }

        // 4. Top flank arc: [p3_top -> p5_top] on circle R2
        for (let j = 0; j < n_flank; j++) {
            const u = j / n_flank;
            const phi = phi_top_start + u * (phi_top_end - phi_top_start);
            sector.push({ x: P7_top.x + R2_val * Math.cos(phi), y: P7_top.y + R2_val * Math.sin(phi) });
        }

        // 5. Top crest arc: [th5 -> half_pitch] on circle ra
        for (let j = 0; j < n_tip; j++) {
            const u = j / n_tip;
            const th = th5 + u * (half_pitch - th5);
            sector.push({ x: ra * Math.cos(th), y: ra * Math.sin(th) });
        }

        // Replicate across all z teeth:
        // Space 0 is at angle 0.0 rad, perfectly matching roller conjugate meshing!
        const pts = [];
        for (let k = 0; k < z; k++) {
            const ang_k = k * pitch_ang;
            const cos_k = Math.cos(ang_k);
            const sin_k = Math.sin(ang_k);
            for (let j = 0; j < sector.length; j++) {
                const pt = sector[j];
                pts.push({
                    x: pt.x * cos_k - pt.y * sin_k,
                    y: pt.x * sin_k + pt.y * cos_k
                });
            }
        }

        return pts;
    },

    /**
     * Generate Chain Transmission Kinematic Path & Roller Positions (Zero-Deviation Conjugate Meshing)
     */
    generateChainKinematics(d1, d2, a, p, X, rotationAngle = 0.0, z1_param, z2_param) {
        const r1 = d1 / 2.0;
        const r2 = d2 / 2.0;
        const z1 = z1_param || Math.round(Math.PI / Math.asin(p / (2.0 * r1)));
        const z2 = z2_param || Math.round(Math.PI / Math.asin(p / (2.0 * r2)));

        const sin_phi = (r2 - r1) / a;
        const phi = Math.asin(Math.min(1.0, Math.max(-1.0, sin_phi)));

        const c1 = { x: 0, y: 0 };
        const c2 = { x: a, y: 0 };

        // Common tangent points (symmetric across x-axis)
        const t1_top = { x: -r1 * Math.sin(phi), y: r1 * Math.cos(phi) };
        const t2_top = { x: a - r2 * Math.sin(phi), y: r2 * Math.cos(phi) };
        const t1_bot = { x: -r1 * Math.sin(phi), y: -r1 * Math.cos(phi) };
        const t2_bot = { x: a - r2 * Math.sin(phi), y: -r2 * Math.cos(phi) };

        const L_span = a * Math.cos(phi);

        // Link counts in each region
        const n_top = L_span / p;
        const n_sp2 = z2 * (Math.PI + 2.0 * phi) / (2.0 * Math.PI);
        const n_bot = L_span / p;
        const n_sp1 = z1 * (Math.PI - 2.0 * phi) / (2.0 * Math.PI);

        const psi1_top = Math.PI / 2.0 + phi;
        const psi1_bot = -Math.PI / 2.0 - phi;
        const psi2_top = Math.PI / 2.0 + phi;
        const psi2_bot = -Math.PI / 2.0 - phi;

        // Continuous link movement offset: u_move in units of links [0, X)
        // rotationAngle is the continuous angular rotation of Sprocket 1
        // One full tooth rotation of Sprocket 1 is 2*PI / z1, which corresponds to 1 link
        const u_move = (rotationAngle / ((2.0 * Math.PI) / z1)) % X;

        // Synchronized Sprocket Rotation Angles
        const theta1 = psi1_bot + (2.0 * n_top + n_sp2 - u_move) * ((2.0 * Math.PI) / z1);
        const theta2 = psi2_top + (n_top - u_move) * ((2.0 * Math.PI) / z2);

        // Position of each roller i along articulated path
        const rollers = [];
        for (let i = 0; i < X; i++) {
            let u = (i + u_move) % X;
            if (u < 0) u += X;

            let pos = { x: 0, y: 0, angle: 0 };

            if (u < n_top) {
                // Top straight span from t1_top to t2_top
                const tau = u / n_top;
                pos.x = t1_top.x + tau * (t2_top.x - t1_top.x);
                pos.y = t1_top.y + tau * (t2_top.y - t1_top.y);
                pos.angle = phi;
            } else if (u < n_top + n_sp2) {
                // Sprocket 2 wrap (CW from psi2_top to psi2_bot)
                const delta_u = u - n_top;
                const th = psi2_top - delta_u * ((2.0 * Math.PI) / z2);
                pos.x = c2.x + r2 * Math.cos(th);
                pos.y = c2.y + r2 * Math.sin(th);
                pos.angle = th - Math.PI / 2.0;
            } else if (u < 2.0 * n_top + n_sp2) {
                // Bottom straight span from t2_bot to t1_bot (with realistic catenary sag)
                const delta_u = u - (n_top + n_sp2);
                const tau = delta_u / n_top;
                const sag = 0.012 * a * Math.sin(tau * Math.PI);
                pos.x = t2_bot.x + tau * (t1_bot.x - t2_bot.x);
                pos.y = t2_bot.y + tau * (t1_bot.y - t2_bot.y) - sag;
                pos.angle = -phi + Math.PI;
            } else {
                // Sprocket 1 wrap (CW from psi1_bot to psi1_top)
                const delta_u = u - (2.0 * n_top + n_sp2);
                const th = psi1_bot - delta_u * ((2.0 * Math.PI) / z1);
                pos.x = c1.x + r1 * Math.cos(th);
                pos.y = c1.y + r1 * Math.sin(th);
                pos.angle = th - Math.PI / 2.0;
            }

            rollers.push(pos);
        }

        return {
            c1,
            c2,
            r1,
            r2,
            z1,
            z2,
            phi,
            t1_top,
            t2_top,
            t1_bot,
            t2_bot,
            L_span,
            theta1,
            theta2,
            rollers
        };
    }
};

// CommonJS support for Node.js test runner
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { ChainCalc };
}


/* === File: chain-canvas.js === */

/**
 * MITCalc Web App - Roller Chain 2D CAD Canvas Visualization Engine
 * Standards: ISO 606 / DIN 8187 / ASME B29.1M
 * Features:
 *   - 2D Canvas rendering of full transmission, sprockets, and articulated roller links.
 *   - 4 View Modes: 'full' (Assembly), 'sprocket1' (Pinion), 'sprocket2' (Wheel), 'mesh' (Mesh Detail).
 *   - Interactive Animation Loop (0.1x to 3.0x speed, pause, reset).
 *   - Rule 11: Mobile Touch Support (1-finger Pan, 2-finger Pinch Zoom, touch-action: none).
 *   - Desktop Mouse Pan (Drag), Wheel Zoom, Double-click auto-fit.
 */

class ChainCanvas {
    constructor(canvasId, options = {}) {
        this.canvas = document.getElementById(canvasId);
        if (!this.canvas) {
            console.error(`Canvas with id "${canvasId}" not found.`);
            return;
        }
        this.ctx = this.canvas.getContext('2d');

        // View options
        this.viewMode = options.viewMode || 'full'; // 'full', 'sprocket1', 'sprocket2', 'mesh'
        this.showPitchCircles = options.showPitchCircles !== false;
        this.showDimensions = options.showDimensions !== false;
        this.showCenterLine = options.showCenterLine !== false;
        this.showLinks = options.showLinks !== false;
        this.showToothContours = options.showToothContours !== false;

        // View transform (Pan & Zoom)
        this.zoom = 1.0;
        this.panX = 0;
        this.panY = 0;
        this.isDragging = false;
        this.dragStartX = 0;
        this.dragStartY = 0;

        // Multi-touch tracking
        this.touches = [];
        this.initialPinchDistance = 0;
        this.initialPinchZoom = 1.0;

        // Animation state
        this.isRunning = true;
        this.speedMultiplier = 1.0;
        this.rotationAngle = 0.0; // Current rotation in radians
        this.lastTimestamp = 0;
        this.animFrameId = null;

        // Current calculation data
        this.calcData = null;

        // Bind events & start loop
        this.initEvents();
        this.startAnimation();
    }

    setData(calcData) {
        this.calcData = calcData;
        this.autoFit();
        this.render();
    }

    setViewMode(mode) {
        this.viewMode = mode;
        this.autoFit();
        this.render();
    }

    setSpeed(speed) {
        this.speedMultiplier = Math.max(0.1, Math.min(3.0, speed));
    }

    toggleAnimation() {
        this.isRunning = !this.isRunning;
        return this.isRunning;
    }

    toggleLinks() {
        this.showLinks = !this.showLinks;
        this.render();
        return this.showLinks;
    }

    resetRotation() {
        this.rotationAngle = 0.0;
        this.render();
    }

    startAnimation() {
        const loop = (timestamp) => {
            if (!this.lastTimestamp) this.lastTimestamp = timestamp;
            const dt = (timestamp - this.lastTimestamp) / 1000.0;
            this.lastTimestamp = timestamp;

            if (this.isRunning && this.calcData) {
                // Angular velocity: omega1 = n1 * 2 * PI / 60 [rad/s]
                // Scale animation speed to visually smooth rotation (approx 0.5 - 1.5 rad/s visually)
                const visualSpeed = 0.75 * this.speedMultiplier;
                this.rotationAngle += visualSpeed * dt;
                if (this.rotationAngle > Math.PI * 2.0 * 100) {
                    this.rotationAngle %= (Math.PI * 2.0);
                }
                this.render();
            }

            this.animFrameId = requestAnimationFrame(loop);
        };
        this.animFrameId = requestAnimationFrame(loop);
    }

    stopAnimation() {
        if (this.animFrameId) {
            cancelAnimationFrame(this.animFrameId);
            this.animFrameId = null;
        }
    }

    autoFit() {
        if (!this.calcData || !this.canvas) return;

        const cw = this.canvas.width;
        const ch = this.canvas.height;
        const res = this.calcData;
        const a = res.a || 300;
        const d1 = res.d1 || 100;
        const d2 = res.d2 || 200;
        const da1 = (res.sprocket1 && res.sprocket1.da) || (d1 + 10);
        const da2 = (res.sprocket2 && res.sprocket2.da) || (d2 + 10);

        if (this.viewMode === 'full') {
            // Full transmission: Sprocket 1 at (0, 0), Sprocket 2 at (a, 0)
            const margin = 1.30;
            const bboxWidth = (a + da1 / 2 + da2 / 2) * margin;
            const bboxHeight = Math.max(da1, da2) * 2.2;

            const scaleX = cw / bboxWidth;
            const scaleY = ch / bboxHeight;
            this.zoom = Math.min(scaleX, scaleY);

            // Center of transmission is at (a / 2, 0)
            this.panX = cw / 2 - (a / 2) * this.zoom;
            this.panY = ch / 2 - 15;
        } else if (this.viewMode === 'sprocket1') {
            // Focus on Sprocket 1 (Pinion)
            const margin = 1.35;
            const scale = Math.min(cw / (da1 * margin), ch / (da1 * margin));
            this.zoom = scale;
            this.panX = cw / 2;
            this.panY = ch / 2;
        } else if (this.viewMode === 'sprocket2') {
            // Focus on Sprocket 2 (Wheel)
            const margin = 1.35;
            const scale = Math.min(cw / (da2 * margin), ch / (da2 * margin));
            this.zoom = scale;
            this.panX = cw / 2 - a * this.zoom;
            this.panY = ch / 2;
        } else if (this.viewMode === 'mesh') {
            // Focus on Mesh detail near top span entrance of Sprocket 1
            const p = res.chain ? res.chain.pitch : 12.7;
            const scale = (ch / (p * 8));
            this.zoom = scale;
            this.panX = cw * 0.45;
            this.panY = ch * 0.55;
        }
    }

    initEvents() {
        // Desktop Mouse Events
        this.canvas.addEventListener('mousedown', (e) => {
            this.isDragging = true;
            this.dragStartX = e.clientX - this.panX;
            this.dragStartY = e.clientY - this.panY;
        });

        window.addEventListener('mousemove', (e) => {
            if (!this.isDragging) return;
            this.panX = e.clientX - this.dragStartX;
            this.panY = e.clientY - this.dragStartY;
            if (!this.isRunning) this.render();
        });

        window.addEventListener('mouseup', () => {
            this.isDragging = false;
        });

        this.canvas.addEventListener('wheel', (e) => {
            e.preventDefault();
            const rect = this.canvas.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;

            const zoomFactor = e.deltaY < 0 ? 1.15 : 0.87;
            const newZoom = Math.max(0.05, Math.min(25.0, this.zoom * zoomFactor));

            // Zoom centered at mouse position
            this.panX = mouseX - (mouseX - this.panX) * (newZoom / this.zoom);
            this.panY = mouseY - (mouseY - this.panY) * (newZoom / this.zoom);
            this.zoom = newZoom;

            if (!this.isRunning) this.render();
        }, { passive: false });

        this.canvas.addEventListener('dblclick', () => {
            this.autoFit();
            if (!this.isRunning) this.render();
        });

        // Mobile Multi-Touch Events (Rule 11)
        this.canvas.addEventListener('touchstart', (e) => {
            e.preventDefault();
            if (e.touches.length === 1) {
                this.isDragging = true;
                this.dragStartX = e.touches[0].clientX - this.panX;
                this.dragStartY = e.touches[0].clientY - this.panY;
            } else if (e.touches.length === 2) {
                this.isDragging = false;
                const dx = e.touches[0].clientX - e.touches[1].clientX;
                const dy = e.touches[0].clientY - e.touches[1].clientY;
                this.initialPinchDistance = Math.hypot(dx, dy);
                this.initialPinchZoom = this.zoom;
            }
        }, { passive: false });

        this.canvas.addEventListener('touchmove', (e) => {
            e.preventDefault();
            if (e.touches.length === 1 && this.isDragging) {
                this.panX = e.touches[0].clientX - this.dragStartX;
                this.panY = e.touches[0].clientY - this.dragStartY;
                if (!this.isRunning) this.render();
            } else if (e.touches.length === 2 && this.initialPinchDistance > 0) {
                const dx = e.touches[0].clientX - e.touches[1].clientX;
                const dy = e.touches[0].clientY - e.touches[1].clientY;
                const currentDist = Math.hypot(dx, dy);
                const scale = currentDist / this.initialPinchDistance;
                this.zoom = Math.max(0.05, Math.min(25.0, this.initialPinchZoom * scale));
                if (!this.isRunning) this.render();
            }
        }, { passive: false });

        this.canvas.addEventListener('touchend', (e) => {
            if (e.touches.length === 0) {
                this.isDragging = false;
                this.initialPinchDistance = 0;
            } else if (e.touches.length === 1) {
                this.isDragging = true;
                this.dragStartX = e.touches[0].clientX - this.panX;
                this.dragStartY = e.touches[0].clientY - this.panY;
            }
        });
    }

    // World to Screen coordinates
    worldToScreen(x, y) {
        return {
            x: this.panX + x * this.zoom,
            y: this.panY - y * this.zoom // Invert Y for engineering coordinate system
        };
    }

    render() {
        const ctx = this.ctx;
        const cw = this.canvas.width;
        const ch = this.canvas.height;

        // Clear canvas
        ctx.fillStyle = '#0f172a'; // Deep slate dark background
        ctx.fillRect(0, 0, cw, ch);

        // Draw engineering grid
        this.drawGrid();

        if (!this.calcData) {
            this.drawNoData();
            return;
        }

        const res = this.calcData;
        const a = res.a || 300;
        const d1 = res.d1 || 100;
        const d2 = res.d2 || 200;
        const z1 = res.z1 || 19;
        const z2 = res.z2 || 40;
        const p = res.p || (res.chain ? res.chain.pitch : 12.7);
        const d3 = res.d3 || (res.chain ? res.chain.d3 : 8.51); // roller diameter
        const b1 = res.b1 || (res.chain ? res.chain.b1 : 7.75);
        const X = res.X_even || res.X_exact || res.X || 100;

        const sp1 = res.sprocket1 || { da: res.da1, df: res.df1, R1: res.R1, bf1: res.bf, rx: res.rx, Dg: res.Dg1, p, d3 };
        const sp2 = res.sprocket2 || { da: res.da2, df: res.df2, R1: res.R1, bf1: res.bf, rx: res.rx, Dg: res.Dg2, p, d3 };
        const da1 = sp1.da || (d1 + 10);
        const da2 = sp2.da || (d2 + 10);

        // Generate full synchronized conjugate kinematics
        const kine = (ChainCalc && ChainCalc.generateChainKinematics) 
            ? ChainCalc.generateChainKinematics(d1, d2, a, p, X, this.rotationAngle, z1, z2)
            : { theta1: this.rotationAngle, theta2: this.rotationAngle * (z1 / z2), rollers: [] };

        ctx.save();

        if (this.viewMode === 'full') {
            // 1. Draw Sprocket 1 at (0, 0)
            this.drawSprocket(0, 0, d1, z1, sp1, kine.theta1, '#38bdf8', 'Đĩa dẫn 1 (Z1=' + z1 + ')');

            // 2. Draw Sprocket 2 at (a, 0)
            this.drawSprocket(a, 0, d2, z2, sp2, kine.theta2, '#fbbf24', 'Đĩa bị dẫn 2 (Z2=' + z2 + ')');

            // 3. Draw Chain Kinematics (Loop & Rollers & Links)
            if (this.showLinks) {
                this.drawChainLoop(kine, p, d3);
            }

            // 4. Center Line & Dimensions
            if (this.showCenterLine) {
                this.drawCenterLine(0, 0, a, 0);
            }
            if (this.showDimensions) {
                this.drawTransmissionDimensions(0, 0, a, 0, d1, d2, da1, da2, a);
            }
        } else if (this.viewMode === 'sprocket1') {
            // Focused on Sprocket 1
            this.drawSprocket(0, 0, d1, z1, sp1, kine.theta1, '#38bdf8', 'Đĩa xích dẫn 1 (Z1=' + z1 + ')');
            if (this.showLinks) {
                this.drawChainLoop(kine, p, d3);
            }
            if (this.showDimensions) {
                this.drawSprocketDimensions(0, 0, d1, sp1);
            }
        } else if (this.viewMode === 'sprocket2') {
            // Focused on Sprocket 2
            this.drawSprocket(a, 0, d2, z2, sp2, kine.theta2, '#fbbf24', 'Đĩa xích bị dẫn 2 (Z2=' + z2 + ')');
            if (this.showLinks) {
                this.drawChainLoop(kine, p, d3);
            }
            if (this.showDimensions) {
                this.drawSprocketDimensions(a, 0, d2, sp2);
            }
        } else if (this.viewMode === 'mesh') {
            // Zoomed Mesh Detail
            this.drawSprocket(0, 0, d1, z1, sp1, kine.theta1, '#38bdf8', 'Khu vực ăn khớp (Mesh Detail)');
            if (this.showLinks) {
                this.drawChainLoop(kine, p, d3, true);
            }
        }

        ctx.restore();

        // Overlay status info
        this.drawOverlayInfo();
    }

    drawGrid() {
        const ctx = this.ctx;
        const cw = this.canvas.width;
        const ch = this.canvas.height;

        ctx.save();
        ctx.strokeStyle = 'rgba(51, 65, 85, 0.4)'; // slate-700
        ctx.lineWidth = 1;

        const gridSize = 50 * this.zoom;
        const minGrid = 30;
        let step = 50;
        while (step * this.zoom < minGrid) step *= 2;
        while (step * this.zoom > minGrid * 4) step /= 2;

        const effectiveStep = step * this.zoom;
        const startX = (this.panX % effectiveStep);
        const startY = (this.panY % effectiveStep);

        ctx.beginPath();
        for (let x = startX; x < cw; x += effectiveStep) {
            ctx.moveTo(x, 0);
            ctx.lineTo(x, ch);
        }
        for (let y = startY; y < ch; y += effectiveStep) {
            ctx.moveTo(0, y);
            ctx.lineTo(cw, y);
        }
        ctx.stroke();
        ctx.restore();
    }

    drawNoData() {
        const ctx = this.ctx;
        ctx.save();
        ctx.fillStyle = '#94a3b8';
        ctx.font = '16px "Segoe UI", sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('Đang chờ nạp dữ liệu tính toán bộ truyền xích con lăn...', this.canvas.width / 2, this.canvas.height / 2);
        ctx.restore();
    }

    /**
     * Draw authentic mechanical Figure-8 dog-bone Link Plate
     */
    drawFigure8LinkPlate(pA, pB, H, waistRatio, fillStyle, strokeStyle) {
        const ctx = this.ctx;
        const dx = pB.x - pA.x;
        const dy = pB.y - pA.y;
        const L = Math.hypot(dx, dy);
        if (L < 1e-4) return;

        const ux = dx / L;
        const uy = dy / L;
        const nx = -uy;
        const ny = ux;

        const R_end = (H / 2.0) * this.zoom;
        const halfWaist = ((H * waistRatio) / 2.0) * this.zoom;
        const ang_u = Math.atan2(uy, ux);

        ctx.save();
        ctx.fillStyle = fillStyle;
        ctx.strokeStyle = strokeStyle;
        ctx.lineWidth = Math.max(1.0, 1.2 * Math.min(2.0, this.zoom));

        ctx.beginPath();

        // 1. Arc around pA (from bottom around to top)
        const n_arc = 10;
        for (let j = 0; j <= n_arc; j++) {
            const th = (ang_u - Math.PI / 2.0) - (Math.PI * j / n_arc);
            const px = pA.x + R_end * Math.cos(th);
            const py = pA.y + R_end * Math.sin(th);
            if (j === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }

        // 2. Top waist curve from pA to pB
        const n_waist = 8;
        for (let j = 1; j < n_waist; j++) {
            const u = j / n_waist;
            const h_u = R_end - (R_end - halfWaist) * Math.sin(u * Math.PI);
            const bx = pA.x + u * dx;
            const by = pA.y + u * dy;
            ctx.lineTo(bx + h_u * nx, by + h_u * ny);
        }

        // 3. Arc around pB (from top around to bottom)
        for (let j = 0; j <= n_arc; j++) {
            const th = (ang_u + Math.PI / 2.0) - (Math.PI * j / n_arc);
            const px = pB.x + R_end * Math.cos(th);
            const py = pB.y + R_end * Math.sin(th);
            ctx.lineTo(px, py);
        }

        // 4. Bottom waist curve from pB to pA
        for (let j = 1; j < n_waist; j++) {
            const u = j / n_waist;
            const h_u = R_end - (R_end - halfWaist) * Math.sin(u * Math.PI);
            const bx = pB.x - u * dx;
            const by = pB.y - u * dy;
            ctx.lineTo(bx - h_u * nx, by - h_u * ny);
        }

        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        ctx.restore();
    }

    /**
     * Draw a Sprocket with ISO 606 tooth profile
     */
    drawSprocket(cx, cy, d, z, sprocketData, angle, color, label) {
        const ctx = this.ctx;
        const da = sprocketData ? sprocketData.da : (d + 10);
        const df = sprocketData ? sprocketData.df : (d - 10);
        const r_pitch = d / 2.0;
        const r_tip = da / 2.0;
        const r_root = df / 2.0;

        // 1. Tooth Contour (True ISO 606 Analytical Contour)
        if (this.showToothContours) {
            ctx.save();
            ctx.strokeStyle = color;
            ctx.fillStyle = 'rgba(30, 41, 59, 0.95)'; // Deep Slate Body
            ctx.lineWidth = Math.max(1.5, 1.8 * Math.min(2.0, this.zoom));

            const pts = (ChainCalc && ChainCalc.generateSprocket2DPoints)
                ? ChainCalc.generateSprocket2DPoints(z, sprocketData)
                : null;

            if (pts && pts.length > 0) {
                ctx.beginPath();
                const cosA = Math.cos(angle);
                const sinA = Math.sin(angle);
                for (let i = 0; i < pts.length; i++) {
                    const px = pts[i].x;
                    const py = pts[i].y;
                    // Rotate by angle and translate by (cx, cy)
                    const wx = cx + px * cosA - py * sinA;
                    const wy = cy + px * sinA + py * cosA;
                    const s = this.worldToScreen(wx, wy);
                    if (i === 0) ctx.moveTo(s.x, s.y);
                    else ctx.lineTo(s.x, s.y);
                }
                ctx.closePath();
                ctx.fill();
                ctx.stroke();
            }
            ctx.restore();
        }

        // 2. Pitch Circle (Đường kính chia d) - Dash-dot line
        if (this.showPitchCircles) {
            ctx.save();
            ctx.strokeStyle = 'rgba(234, 179, 8, 0.85)'; // Amber gold
            ctx.lineWidth = 1.2;
            ctx.setLineDash([8, 3, 2, 3]);
            ctx.beginPath();
            const scCenter = this.worldToScreen(cx, cy);
            ctx.arc(scCenter.x, scCenter.y, r_pitch * this.zoom, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
        }

        // 3. Bore hole & Hub representation
        ctx.save();
        ctx.fillStyle = '#0f172a';
        ctx.strokeStyle = '#475569';
        ctx.lineWidth = 1.5;
        const r_bore = r_root * 0.38;
        const scC = this.worldToScreen(cx, cy);
        ctx.beginPath();
        ctx.arc(scC.x, scC.y, r_bore * this.zoom, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();

        // Center cross mark
        ctx.strokeStyle = '#94a3b8';
        ctx.lineWidth = 1;
        const crossL = Math.max(8, r_bore * 0.7 * this.zoom);
        ctx.beginPath();
        ctx.moveTo(scC.x - crossL, scC.y);
        ctx.lineTo(scC.x + crossL, scC.y);
        ctx.moveTo(scC.x, scC.y - crossL);
        ctx.lineTo(scC.x, scC.y + crossL);
        ctx.stroke();
        ctx.restore();

        // 4. Label
        ctx.save();
        ctx.fillStyle = '#e2e8f0';
        ctx.font = '12px "Segoe UI", sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(label, scC.x, scC.y + (r_tip + 22) * this.zoom);
        ctx.restore();
    }

    /**
     * Draw the complete articulated Roller Chain Loop
     */
    drawChainLoop(kine, p, d3, detailed = false) {
        const ctx = this.ctx;
        if (!kine || !kine.rollers || kine.rollers.length === 0) return;

        const rollers = kine.rollers;
        const rollerR = (d3 / 2.0);
        const H_plate = 0.88 * p;
        const waist = 0.78;

        ctx.save();

        // Screen coordinates of all rollers
        const screenRollers = rollers.map(r => this.worldToScreen(r.x, r.y));

        // 1. Draw Pitch Path (Đường tâm ăn khớp xích)
        ctx.strokeStyle = 'rgba(148, 163, 184, 0.35)';
        ctx.lineWidth = 1.0;
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        for (let i = 0; i < screenRollers.length; i++) {
            const s = screenRollers[i];
            if (i === 0) ctx.moveTo(s.x, s.y);
            else ctx.lineTo(s.x, s.y);
        }
        ctx.closePath();
        ctx.stroke();
        ctx.setLineDash([]);

        // 2. Pass 1: Inner Link Plates (odd indices)
        for (let i = 0; i < screenRollers.length; i++) {
            if (i % 2 === 1) {
                const nextIdx = (i + 1) % screenRollers.length;
                this.drawFigure8LinkPlate(screenRollers[i], screenRollers[nextIdx], H_plate, waist, 'rgba(51, 65, 85, 0.40)', '#475569');
            }
        }

        // 3. Pass 2: Rollers (Con lăn) seated in tooth gullets
        for (let i = 0; i < screenRollers.length; i++) {
            const s = screenRollers[i];
            const rScreen = Math.max(2.5, rollerR * this.zoom);

            ctx.fillStyle = '#0284c7'; // Sky blue roller body
            ctx.strokeStyle = '#38bdf8';
            ctx.lineWidth = 1.2;
            ctx.beginPath();
            ctx.arc(s.x, s.y, rScreen, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();
        }

        // 4. Pass 3: Outer Link Plates (even indices) with semi-transparent metallic styling
        for (let i = 0; i < screenRollers.length; i++) {
            if (i % 2 === 0) {
                const nextIdx = (i + 1) % screenRollers.length;
                this.drawFigure8LinkPlate(screenRollers[i], screenRollers[nextIdx], H_plate, waist, 'rgba(148, 163, 184, 0.40)', '#cbd5e1');
            }
        }

        // 5. Pass 4: Pins (Chốt xích) with rivet heads
        for (let i = 0; i < screenRollers.length; i++) {
            const s = screenRollers[i];
            const rScreen = Math.max(2.5, rollerR * this.zoom);
            if (rScreen > 3.0) {
                const pinR = Math.max(1.5, rScreen * 0.38);
                ctx.fillStyle = '#0f172a';
                ctx.strokeStyle = '#94a3b8';
                ctx.lineWidth = 1.0;
                ctx.beginPath();
                ctx.arc(s.x, s.y, pinR, 0, Math.PI * 2);
                ctx.fill();
                ctx.stroke();
            }
        }

        ctx.restore();
    }

    /**
     * Draw Center Line connecting axes
     */
    drawCenterLine(x1, y1, x2, y2) {
        const ctx = this.ctx;
        ctx.save();
        ctx.strokeStyle = '#ef4444'; // Red center line
        ctx.lineWidth = 1.2;
        ctx.setLineDash([12, 4, 3, 4]);

        const s1 = this.worldToScreen(x1, y1);
        const s2 = this.worldToScreen(x2, y2);

        // Extend slightly beyond sprockets
        const ext = 40;
        ctx.beginPath();
        ctx.moveTo(s1.x - ext, s1.y);
        ctx.lineTo(s2.x + ext, s2.y);
        ctx.stroke();

        ctx.restore();
    }

    /**
     * Draw Transmission Dimensions (Axis distance a, tip diameters)
     */
    drawTransmissionDimensions(x1, y1, x2, y2, d1, d2, da1, da2, a) {
        const ctx = this.ctx;
        ctx.save();

        const s1 = this.worldToScreen(x1, y1);
        const s2 = this.worldToScreen(x2, y2);

        // Dimension: Axis distance a [mm]
        const dimY = s1.y + Math.max(da1, da2) * 0.65 * this.zoom + 25;
        ctx.strokeStyle = '#a855f7'; // Purple dimension line
        ctx.fillStyle = '#c084fc';
        ctx.lineWidth = 1.0;

        // Extension lines
        ctx.beginPath();
        ctx.moveTo(s1.x, s1.y + 10);
        ctx.lineTo(s1.x, dimY + 8);
        ctx.moveTo(s2.x, s2.y + 10);
        ctx.lineTo(s2.x, dimY + 8);
        ctx.stroke();

        // Dimension line with arrows
        ctx.beginPath();
        ctx.moveTo(s1.x, dimY);
        ctx.lineTo(s2.x, dimY);
        ctx.stroke();
        this.drawArrow(s1.x, dimY, 1, 0);
        this.drawArrow(s2.x, dimY, -1, 0);

        // Text
        ctx.font = '12px "Segoe UI", sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(`a = ${a.toFixed(2)} mm`, (s1.x + s2.x) / 2, dimY - 6);

        ctx.restore();
    }

    /**
     * Draw Sprocket specific dimensions
     */
    drawSprocketDimensions(cx, cy, d, sprocketData) {
        const ctx = this.ctx;
        if (!sprocketData) return;
        ctx.save();

        const da = sprocketData.da;
        const df = sprocketData.df;
        const s = this.worldToScreen(cx, cy);

        ctx.fillStyle = '#38bdf8';
        ctx.font = '12px "Segoe UI", sans-serif';
        ctx.textAlign = 'left';

        const infoX = s.x + (da / 2 + 15) * this.zoom;
        const infoY = s.y - 40;

        ctx.fillText(`d  = ${d.toFixed(2)} mm (Vòng chia)`, infoX, infoY);
        ctx.fillText(`da = ${da.toFixed(2)} mm (Vòng đỉnh)`, infoX, infoY + 18);
        ctx.fillText(`df = ${df.toFixed(2)} mm (Vòng đáy)`, infoX, infoY + 36);
        ctx.fillText(`R1 = ${sprocketData.R1.toFixed(2)} mm (Lượn đáy)`, infoX, infoY + 54);
        ctx.fillText(`bf1 = ${sprocketData.bf1.toFixed(2)} mm (Rộng răng)`, infoX, infoY + 72);

        ctx.restore();
    }

    drawArrow(x, y, dirX, dirY, size = 6) {
        const ctx = this.ctx;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + dirX * size - dirY * (size / 2), y + dirY * size + dirX * (size / 2));
        ctx.lineTo(x + dirX * size + dirY * (size / 2), y + dirY * size - dirX * (size / 2));
        ctx.closePath();
        ctx.fill();
    }

    drawOverlayInfo() {
        const ctx = this.ctx;
        const cw = this.canvas.width;

        ctx.save();
        ctx.fillStyle = 'rgba(15, 23, 42, 0.75)';
        ctx.fillRect(10, 10, 240, 75);
        ctx.strokeStyle = '#334155';
        ctx.strokeRect(10, 10, 240, 75);

        ctx.fillStyle = '#38bdf8';
        ctx.font = 'bold 12px "Segoe UI", sans-serif';
        ctx.fillText('MÔ PHỎNG 2D BỘ TRUYỀN XÍCH', 20, 28);

        ctx.fillStyle = '#94a3b8';
        ctx.font = '11px "Segoe UI", sans-serif';
        ctx.fillText(`Thu phóng: ${(this.zoom * 100).toFixed(0)}%`, 20, 46);
        ctx.fillText(`Chế độ: ${this.viewMode.toUpperCase()} | Tốc độ: ${this.speedMultiplier}x`, 20, 62);
        ctx.fillText(this.isRunning ? '▶ Đang chạy mô phỏng' : '⏸ Đang tạm dừng', 20, 78);

        ctx.restore();
    }
}

// Global expose
if (typeof window !== 'undefined') {
    window.ChainCanvas = ChainCanvas;
}


